<?php
declare(strict_types=1);
require_once __DIR__.'/../../app/Database.php';
require_once __DIR__.'/../../app/Auth.php';
exigirAdmin();
header('Content-Type: application/json; charset=utf-8');
function respuesta(bool $ok,array $data=[],int $status=200):never{http_response_code($status);echo json_encode(array_merge(['ok'=>$ok],$data),JSON_UNESCAPED_UNICODE);exit;}
function eventoExiste(PDO $db,int $id):array{$s=$db->prepare('SELECT id,nombre,estado FROM eventos WHERE id=:id LIMIT 1');$s->execute([':id'=>$id]);$r=$s->fetch(PDO::FETCH_ASSOC);if(!$r)throw new RuntimeException('Evento no encontrado.');return $r;}
function obtenerSorteo(PDO $db,int $eventoId,int $usuarioId,bool $crear=false):?array{$s=$db->prepare('SELECT id,evento_id,estado FROM sorteos WHERE evento_id=:evento_id LIMIT 1');$s->execute([':evento_id'=>$eventoId]);$r=$s->fetch(PDO::FETCH_ASSOC);if($r||!$crear)return $r?:null;$s=$db->prepare("INSERT INTO sorteos (evento_id,creado_por,estado) VALUES (:evento_id,:creado_por,'ACTIVO')");$s->execute([':evento_id'=>$eventoId,':creado_por'=>$usuarioId]);return ['id'=>(int)$db->lastInsertId(),'evento_id'=>$eventoId,'estado'=>'ACTIVO'];}
function candidatosDisponibles(PDO $db,int $eventoId,int $sorteoId):array{$s=$db->prepare("SELECT DISTINCT ec.id,ec.cod,ec.cedula,ec.apellidos_nombres,ec.area,ec.empresa FROM evento_colaboradores ec INNER JOIN registros r ON r.colaborador_id=ec.id AND r.evento_id=ec.evento_id WHERE ec.evento_id=:evento_id AND r.tipo_registro='ASISTENCIA' AND UPPER(TRIM(COALESCE(ec.estado,'')))='ACTIVO' AND NOT EXISTS (SELECT 1 FROM sorteo_ganadores sg WHERE sg.sorteo_id=:sg AND sg.colaborador_id=ec.id) AND NOT EXISTS (SELECT 1 FROM sorteo_intentos si WHERE si.sorteo_id=:si AND si.colaborador_id=ec.id AND si.resultado='NO_PRESENTE') ORDER BY ec.apellidos_nombres");$s->execute([':evento_id'=>$eventoId,':sg'=>$sorteoId,':si'=>$sorteoId]);return $s->fetchAll(PDO::FETCH_ASSOC);}
try{
$db=Database::connection();$action=(string)($_POST['action']??$_GET['action']??'');$eventoId=(int)($_POST['evento_id']??$_GET['evento_id']??0);if($eventoId<=0)respuesta(false,['message'=>'Evento no válido.'],400);$evento=eventoExiste($db,$eventoId);$usuarioId=(int)$_SESSION['usuario_id'];
if($evento['estado']==='FINALIZADO'&&$action!=='bootstrap')respuesta(false,['message'=>'El evento está FINALIZADO. El sorteo es de solo lectura.'],409);
$sorteo=obtenerSorteo($db,$eventoId,$usuarioId,$action!=='bootstrap');
if(!$sorteo){if($action==='bootstrap')respuesta(true,['evento'=>$evento,'sorteo'=>null,'premios'=>[],'ganadores'=>[],'cantidad_disponibles'=>0]);respuesta(false,['message'=>'No existe un sorteo para este evento.'],404);}
$sorteoId=(int)$sorteo['id'];if($sorteo['estado']==='FINALIZADO'&&$action!=='bootstrap')respuesta(false,['message'=>'El sorteo está FINALIZADO y no admite modificaciones.'],409);
if($action==='bootstrap'){$s=$db->prepare('SELECT id,nombre,posicion,estado,creado_en FROM sorteo_premios WHERE sorteo_id=:id ORDER BY posicion,id');$s->execute([':id'=>$sorteoId]);$premios=$s->fetchAll(PDO::FETCH_ASSOC);$s=$db->prepare('SELECT sg.id,sg.premio_id,sp.nombre AS premio,ec.id AS colaborador_id,ec.cod,ec.cedula,ec.apellidos_nombres,ec.area,ec.empresa,sg.fecha_hora FROM sorteo_ganadores sg INNER JOIN sorteo_premios sp ON sp.id=sg.premio_id INNER JOIN evento_colaboradores ec ON ec.id=sg.colaborador_id WHERE sg.sorteo_id=:id ORDER BY sg.id');$s->execute([':id'=>$sorteoId]);$ganadores=$s->fetchAll(PDO::FETCH_ASSOC);$candidatos=candidatosDisponibles($db,$eventoId,$sorteoId);respuesta(true,['evento'=>$evento,'sorteo'=>$sorteo,'premios'=>$premios,'ganadores'=>$ganadores,'cantidad_disponibles'=>count($candidatos)]);}
if($action==='crear_premio'){$nombre=trim((string)($_POST['nombre']??''));if($nombre==='')respuesta(false,['message'=>'Ingrese el nombre del premio.'],400);$s=$db->prepare('SELECT COALESCE(MAX(posicion),0)+1 FROM sorteo_premios WHERE sorteo_id=:id');$s->execute([':id'=>$sorteoId]);$pos=(int)$s->fetchColumn();$s=$db->prepare("INSERT INTO sorteo_premios (sorteo_id,nombre,posicion,estado) VALUES (:id,:nombre,:pos,'PENDIENTE')");$s->execute([':id'=>$sorteoId,':nombre'=>$nombre,':pos'=>$pos]);respuesta(true,['premio_id'=>(int)$db->lastInsertId(),'message'=>'Premio creado correctamente.']);}
if($action==='candidatos'){$premioId=(int)($_POST['premio_id']??0);if($premioId<=0)respuesta(false,['message'=>'Premio no válido.'],400);$s=$db->prepare('SELECT id,nombre,estado FROM sorteo_premios WHERE id=:id AND sorteo_id=:sid LIMIT 1');$s->execute([':id'=>$premioId,':sid'=>$sorteoId]);$premio=$s->fetch(PDO::FETCH_ASSOC);if(!$premio)respuesta(false,['message'=>'Premio no encontrado.'],404);if($premio['estado']==='COMPLETADO')respuesta(false,['message'=>'Este premio ya fue completado.'],409);$candidatos=candidatosDisponibles($db,$eventoId,$sorteoId);if(!$candidatos)respuesta(false,['message'=>'No quedan colaboradores disponibles para este sorteo.'],409);$indice=random_int(0,count($candidatos)-1);$ganador=$candidatos[$indice];$s=$db->prepare("UPDATE sorteo_premios SET estado='EN_PROCESO' WHERE id=:id AND estado='PENDIENTE'");$s->execute([':id'=>$premioId]);respuesta(true,['premio'=>$premio,'candidatos'=>$candidatos,'indice_ganador'=>$indice,'ganador'=>$ganador]);}
if($action==='resolver'){$premioId=(int)($_POST['premio_id']??0);$colaboradorId=(int)($_POST['colaborador_id']??0);$presente=(int)($_POST['presente']??0);if($premioId<=0||$colaboradorId<=0)respuesta(false,['message'=>'Datos del ganador no válidos.'],400);$s=$db->prepare('SELECT id,nombre,estado FROM sorteo_premios WHERE id=:id AND sorteo_id=:sid LIMIT 1');$s->execute([':id'=>$premioId,':sid'=>$sorteoId]);$premio=$s->fetch(PDO::FETCH_ASSOC);if(!$premio)respuesta(false,['message'=>'Premio no encontrado.'],404);if($premio['estado']==='COMPLETADO')respuesta(false,['message'=>'Este premio ya fue completado.'],409);$s=$db->prepare('SELECT id,cod,cedula,apellidos_nombres,area,empresa FROM evento_colaboradores WHERE id=:id AND evento_id=:evento LIMIT 1');$s->execute([':id'=>$colaboradorId,':evento'=>$eventoId]);$colaborador=$s->fetch(PDO::FETCH_ASSOC);if(!$colaborador)respuesta(false,['message'=>'Colaborador no encontrado.'],404);$s=$db->prepare("SELECT COUNT(*) FROM registros WHERE evento_id=:evento AND colaborador_id=:colaborador AND tipo_registro='ASISTENCIA'");$s->execute([':evento'=>$eventoId,':colaborador'=>$colaboradorId]);if((int)$s->fetchColumn()===0)respuesta(false,['message'=>'El colaborador no tiene asistencia registrada.'],409);$s=$db->prepare('SELECT COUNT(*) FROM sorteo_ganadores WHERE sorteo_id=:sorteo AND colaborador_id=:colaborador');$s->execute([':sorteo'=>$sorteoId,':colaborador'=>$colaboradorId]);if((int)$s->fetchColumn()>0)respuesta(false,['message'=>'Este colaborador ya ganó un premio en este evento.'],409);$s=$db->prepare("SELECT COUNT(*) FROM sorteo_intentos WHERE sorteo_id=:sorteo AND colaborador_id=:colaborador AND resultado='NO_PRESENTE'");$s->execute([':sorteo'=>$sorteoId,':colaborador'=>$colaboradorId]);if((int)$s->fetchColumn()>0)respuesta(false,['message'=>'Este colaborador ya fue marcado como no presente.'],409);$db->beginTransaction();try{if($presente===1){$s=$db->prepare("INSERT INTO sorteo_intentos (sorteo_id,premio_id,colaborador_id,resultado,usuario_id) VALUES (:sorteo,:premio,:colaborador,'GANADOR',:usuario)");$s->execute([':sorteo'=>$sorteoId,':premio'=>$premioId,':colaborador'=>$colaboradorId,':usuario'=>$usuarioId]);$s=$db->prepare('INSERT INTO sorteo_ganadores (sorteo_id,premio_id,colaborador_id,usuario_id) VALUES (:sorteo,:premio,:colaborador,:usuario)');$s->execute([':sorteo'=>$sorteoId,':premio'=>$premioId,':colaborador'=>$colaboradorId,':usuario'=>$usuarioId]);$s=$db->prepare("UPDATE sorteo_premios SET estado='COMPLETADO' WHERE id=:id AND estado<>'COMPLETADO'");$s->execute([':id'=>$premioId]);$db->commit();respuesta(true,['resultado'=>'GANADOR','message'=>'Ganador registrado correctamente.','colaborador'=>$colaborador,'premio'=>$premio]);}$s=$db->prepare("INSERT INTO sorteo_intentos (sorteo_id,premio_id,colaborador_id,resultado,usuario_id) VALUES (:sorteo,:premio,:colaborador,'NO_PRESENTE',:usuario)");$s->execute([':sorteo'=>$sorteoId,':premio'=>$premioId,':colaborador'=>$colaboradorId,':usuario'=>$usuarioId]);$db->commit();respuesta(true,['resultado'=>'NO_PRESENTE','message'=>'Colaborador excluido. Se realizará otro giro.','colaborador'=>$colaborador,'premio'=>$premio]);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}}
if($action==='finalizar'){$s=$db->prepare("UPDATE sorteos SET estado='FINALIZADO' WHERE id=:id AND estado<>'FINALIZADO'");$s->execute([':id'=>$sorteoId]);respuesta(true,['message'=>'Sorteo finalizado.']);}
respuesta(false,['message'=>'Acción no reconocida.'],400);
}catch(Throwable $e){respuesta(false,['message'=>$e->getMessage()],500);}